function zxingFormats(){let z=window.ZXingBrowser||window.ZXing;if(!z||!z.BarcodeFormat)return undefined;return [z.BarcodeFormat.EAN_13,z.BarcodeFormat.EAN_8,z.BarcodeFormat.UPC_A,z.BarcodeFormat.UPC_E,z.BarcodeFormat.CODE_128].filter(Boolean)}
function scannerConstraints(fallback=false){return fallback?{video:true,audio:false}:{video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false}}
function scannerLog(msg,data){try{console.log('SCANNER: '+msg+(data?' '+data:''))}catch(e){}}
