function initInventory(){
let openForm=document.getElementById('inventoryOpenForm'),workspace=document.getElementById('inventoryWorkspace');if(!openForm||!workspace)return;
let shell=document.querySelector('.inventory-shell'),canWrite=shell?.dataset.canWrite==='true';
let idInput=document.getElementById('inventoryId'),linesBox=document.getElementById('inventoryLines'),message=document.getElementById('inventoryMessage'),search=document.getElementById('inventorySearch'),mode=document.getElementById('inventoryMode'),progressText=document.getElementById('inventoryProgress'),progressBar=document.getElementById('inventoryProgressBar'),statusText=document.getElementById('inventoryStatusText'),terminalActions=document.getElementById('inventoryTerminalActions');
let listForm=document.getElementById('inventoryListFilters'),listBox=document.getElementById('inventoryList'),listMsg=document.getElementById('inventoryListMessage'),listStatus=document.getElementById('inventoryListStatus'),listType=document.getElementById('inventoryListType'),listWarehouse=document.getElementById('inventoryListWarehouse'),listResponsible=document.getElementById('inventoryListResponsible'),listFrom=document.getElementById('inventoryListFrom'),listTo=document.getElementById('inventoryListTo'),listPrev=document.getElementById('inventoryListPrev'),listNext=document.getElementById('inventoryListNext'),listPaging=document.getElementById('inventoryListPaging'),listClear=document.getElementById('inventoryListClear');
let createTotal=document.getElementById('inventoryCreateTotal'),createBlind=document.getElementById('inventoryCreateBlind'),createWarehouse=document.getElementById('inventoryCreateWarehouse');
let current=null,filter='pending',listOffset=0,listLimit=30;
const inventoryCreatePendingKey='pendingInventoryCreate';
function setMessage(text,kind=''){setFeedback(message,kind==='ok'?'success':kind,text)}
function setListMessage(text,kind=''){setFeedback(listMsg,kind==='ok'?'success':kind,text)}
function readInventoryCreatePending(){let raw=sessionStorage.getItem(inventoryCreatePendingKey);if(!raw)return null;try{let p=JSON.parse(raw);if(!p||!['TOTAL','BLIND'].includes(p.type)||typeof p.operation_id!=='string'||!p.operation_id.trim()||(p.type==='TOTAL'&&!(+p.warehouse_id>0)))throw new Error('invalid pending inventory creation');return p}catch(e){sessionStorage.removeItem(inventoryCreatePendingKey);return null}}
function saveInventoryCreatePending(p){sessionStorage.setItem(inventoryCreatePendingKey,JSON.stringify(p))}
function clearInventoryCreatePending(){sessionStorage.removeItem(inventoryCreatePendingKey)}
function applyInventoryCreatePending(){let p=readInventoryCreatePending(),totalBtn=createTotal?.querySelector('button[type="submit"]'),blindBtn=createBlind?.querySelector('button[type="submit"]');if(!p){if(createWarehouse)createWarehouse.disabled=false;if(totalBtn){totalBtn.disabled=false;totalBtn.textContent='Criar inventário total'}if(blindBtn){blindBtn.disabled=false;blindBtn.textContent='Criar inventário cego'}return}if(createWarehouse){if(p.type==='TOTAL')createWarehouse.value=String(p.warehouse_id);createWarehouse.disabled=true}if(totalBtn){totalBtn.disabled=p.type!=='TOTAL';totalBtn.textContent=p.type==='TOTAL'?'Reenviar criação pendente':'Criar inventário total'}if(blindBtn){blindBtn.disabled=p.type!=='BLIND';blindBtn.textContent=p.type==='BLIND'?'Reenviar criação pendente':'Criar inventário cego'}setListMessage('Existe uma criação de inventário pendente de confirmação. Reenvie a mesma tentativa antes de iniciar outra.','error')}
function definitiveInventoryCreateError(err){let status=Number(err&&err.status||0);return status>=400&&status<500}
function statusLabel(s){return ({OPEN:'Aberto',COUNTING:'Em contagem',REVIEW:'Em revisão',COMPLETED:'Concluído',CANCELLED:'Cancelado'})[s]||s}
function inventoryTypeLabel(t){return t==='TOTAL'?'Total':t==='BLIND'?'Cego':t}
function inventoryStateLabel(s){return s==='MATCH'?'Conferido':s==='DIVERGENT'?'Divergente':s}
function actionLabel(s){return s==='OPEN'||s==='COUNTING'?'Continuar contagem':s==='REVIEW'?'Revisar inventário':'Ver histórico'}
function counted(line){return line.physical_quantity!==null&&line.physical_quantity!==undefined}
function reviewMode(){return !!(current&&current.review_mode)}
function historyMode(){return !!(current&&current.history_mode)}
function canEdit(){return canWrite&&current&&!reviewMode()&&!historyMode()&&(current.status==='OPEN'||current.status==='COUNTING')}
function matches(line){let q=normalizeBarcode(search.value).toLowerCase();if(!q)return true;return [line.description,line.code,line.barcode,String(line.sku_id)].some(v=>String(v||'').toLowerCase().includes(q))}
function visibleByFilter(line){if(filter==='all')return true;if(reviewMode())return filter==='pending'?line.state==='DIVERGENT':line.state==='MATCH';if(historyMode()){if(!line.state)return true;return filter==='pending'?line.state==='DIVERGENT':line.state==='MATCH'}return filter==='counted'?counted(line):!counted(line)}
function setFilterLabels(){let labels=(reviewMode()||historyMode())?{pending:'Divergentes',counted:'Conferidos',all:'Todos'}:{pending:'Pendentes',counted:'Contados',all:'Todos'};document.querySelectorAll('[data-inventory-filter]').forEach(b=>{b.textContent=labels[b.dataset.inventoryFilter]||b.textContent})}
function updateHeader(){
 if(!current)return;
 if(historyMode()){let divergent=current.lines.filter(x=>x.state==='DIVERGENT').length,known=current.lines.filter(x=>x.state).length;progressText.textContent=current.reference_revealed?(divergent+' divergência(s) finais'):'Histórico preservado';progressBar.value=current.reference_revealed&&known?Math.floor((known-divergent)*100/known):0;statusText.textContent=statusLabel(current.status)+' · registro histórico';mode.hidden=false;mode.textContent=inventoryTypeLabel(current.type);return}
 if(reviewMode()){let total=current.lines.length,match=current.lines.filter(x=>x.state==='MATCH').length,div=current.lines.filter(x=>x.state==='DIVERGENT').length,pending=current.lines.filter(x=>x.recount_available).length,confirmed=current.lines.filter(x=>x.state==='DIVERGENT'&&!x.recount_available&&x.recount_quantity!==null&&x.recount_quantity!==undefined).length;progressText.textContent=total+' itens · '+match+' conferidos · '+div+' divergentes';progressBar.value=total?Math.floor(match*100/total):100;statusText.textContent='Em revisão · '+pending+' aguardando recontagem · '+confirmed+' divergência(s) confirmada(s)';mode.hidden=false;mode.textContent=inventoryTypeLabel(current.type);return}
 progressText.textContent=current.counted+' de '+current.total+' itens contados';progressBar.value=current.progress_percent||0;statusText.textContent=statusLabel(current.status)+' · '+(current.progress_percent||0)+'%';mode.hidden=false;mode.textContent=inventoryTypeLabel(current.type)
}
function recompute(){if(reviewMode()||historyMode())return;current.counted=current.lines.filter(counted).length;current.total=current.lines.length;current.progress_percent=current.total?Math.floor(current.counted*100/current.total):0}
function auditTime(v){return v?new Date(v).toLocaleString('pt-BR'):''}
function addAuditRow(box,label,value){if(!value)return;let p=document.createElement('p'),strong=document.createElement('strong'),span=document.createElement('span');strong.textContent=label+': ';span.textContent=value;p.append(strong,span);box.append(p)}
function renderTerminalActions(){
 terminalActions.textContent='';terminalActions.hidden=false;
 if(historyMode()){let box=document.createElement('div');box.className='inventory-history-audit';addAuditRow(box,'Responsável inicial',current.responsible_by);addAuditRow(box,'Iniciado em',auditTime(current.started_at));addAuditRow(box,'Snapshot em',auditTime(current.snapshot_at));if(current.status==='COMPLETED'){addAuditRow(box,'Concluído por',current.completed_by);addAuditRow(box,'Concluído em',auditTime(current.completed_at));addAuditRow(box,'Observação',current.completion_note)}if(current.status==='CANCELLED'){addAuditRow(box,'Cancelado por',current.cancelled_by);addAuditRow(box,'Cancelado em',auditTime(current.cancelled_at));addAuditRow(box,'Motivo',current.cancellation_reason)}if(!current.reference_revealed){let warn=document.createElement('p');warn.className='hint';warn.textContent='Referência e divergência permanecem ocultas porque este inventário cego foi cancelado antes da revisão.';box.append(warn)}terminalActions.append(box);return}
 if(!canWrite){terminalActions.hidden=true;return}
 let canCancel=current.status==='OPEN'||current.status==='COUNTING'||current.status==='REVIEW';
 if(reviewMode()){let unresolved=current.lines.some(x=>x.recount_available),finalDivergent=current.lines.some(x=>x.state==='DIVERGENT'&&!x.recount_available);let form=document.createElement('form');form.className='inventory-terminal-form';let lab=document.createElement('label');lab.textContent=finalDivergent?'Observação de conclusão (obrigatória com divergência final)':'Observação de conclusão (opcional)';let note=document.createElement('textarea');note.maxLength=1000;note.rows=3;if(finalDivergent){note.required=true;note.minLength=5}lab.append(note);let btn=document.createElement('button');btn.type='submit';btn.textContent='Concluir inventário';btn.disabled=unresolved;form.append(lab,btn);if(unresolved){let hint=document.createElement('p');hint.className='hint';hint.textContent='Conclua a recontagem formal de todas as divergências antes de encerrar.';form.append(hint)}form.addEventListener('submit',async e=>{e.preventDefault();btn.disabled=true;setMessage('Concluindo inventário…');try{current=await api('/api/inventory-validations/'+current.id+'/complete',{method:'POST',body:JSON.stringify({completion_note:note.value})});current.history_mode=true;current.review_mode=false;filter='all';setMessage('Inventário concluído.','ok');render();loadList()}catch(err){btn.disabled=unresolved;setMessage(uncertainWriteError(err)?'Não foi possível confirmar a conclusão. Reenvie a mesma conclusão, sem alterar a observação.':uiErrorMessage(err,'Não foi possível concluir o inventário.'),'error')}});terminalActions.append(form)}
 if(canCancel){let form=document.createElement('form');form.className='inventory-terminal-form inventory-cancel-form';let lab=document.createElement('label');lab.textContent='Motivo do cancelamento';let reason=document.createElement('textarea');reason.required=true;reason.minLength=5;reason.maxLength=1000;reason.rows=3;lab.append(reason);let btn=document.createElement('button');btn.type='submit';btn.className='danger';btn.textContent='Cancelar inventário';form.append(lab,btn);let hint=document.createElement('p');hint.className='hint';hint.textContent='Cancelar não altera o estoque e preserva o histórico registrado.';form.append(hint);form.addEventListener('submit',async e=>{e.preventDefault();btn.disabled=true;setMessage('Cancelando inventário…');try{current=await api('/api/inventory-validations/'+current.id+'/cancel',{method:'POST',body:JSON.stringify({cancellation_reason:reason.value})});current.history_mode=true;current.review_mode=false;filter='all';setMessage('Inventário cancelado.','ok');render();loadList()}catch(err){btn.disabled=false;setMessage(uncertainWriteError(err)?'Não foi possível confirmar o cancelamento. Reenvie o mesmo cancelamento, sem alterar o motivo.':uiErrorMessage(err,'Não foi possível cancelar o inventário.'),'error')}});terminalActions.append(form)}
 if(!terminalActions.children.length)terminalActions.hidden=true
}
function appendReviewCard(line){let card=document.createElement('article');card.className='inventory-line inventory-review-line'+(line.state==='DIVERGENT'?' divergent':' match');card.dataset.skuId=line.sku_id;let head=document.createElement('div');head.className='inventory-line-head';let title=document.createElement('div'),strong=document.createElement('strong'),meta=document.createElement('small');strong.textContent=line.description;meta.textContent='SKU '+line.code+(line.barcode?' · '+line.barcode:'')+' · '+line.unit;title.append(strong,meta);let badge=document.createElement('span');badge.className='badge';badge.textContent=inventoryStateLabel(line.state);head.append(title,badge);card.append(head);let compare=document.createElement('div');compare.className='inventory-review-grid';[['Primeira contagem',line.first_quantity],['Referência',line.reference_quantity],['Diferença',line.difference]].forEach(pair=>{let box=document.createElement('div'),sm=document.createElement('small'),val=document.createElement('strong');sm.textContent=pair[0];val.textContent=pair[1]+' '+line.unit;box.append(sm,val);compare.append(box)});card.append(compare);let audit=document.createElement('small');audit.className='hint inventory-audit';audit.textContent='Primeira contagem'+(line.first_counted_by?' por '+line.first_counted_by:'')+(line.first_counted_at?' · '+auditTime(line.first_counted_at):'');card.append(audit);if(line.recount_quantity!==null&&line.recount_quantity!==undefined){let recount=document.createElement('div');recount.className='inventory-recount-result';let rs=document.createElement('strong'),rm=document.createElement('small');rs.textContent='Recontagem: '+line.recount_quantity+' '+line.unit;rm.textContent=(line.recounted_by?' por '+line.recounted_by:'')+(line.recounted_at?' · '+auditTime(line.recounted_at):'');recount.append(rs,rm);card.append(recount)}if(canWrite&&line.recount_available){let form=document.createElement('form');form.className='inventory-count-form inventory-recount-form';let lab=document.createElement('label');lab.textContent='Recontagem física ('+line.unit+')';let input=document.createElement('input');input.inputMode='decimal';input.autocomplete='off';input.placeholder='0';input.required=true;lab.append(input);let save=document.createElement('button');save.type='submit';save.textContent='Registrar recontagem';form.append(lab,save);form.addEventListener('submit',async e=>{e.preventDefault();save.disabled=true;setMessage('Salvando recontagem…');try{let out=await api('/api/inventory-validations/'+current.id+'/lines/'+line.sku_id+'/recount',{method:'PUT',body:JSON.stringify({physical_quantity:requestDecimal(input.value),expected_version:line.version})});Object.assign(line,out.line);setMessage('Recontagem salva.','ok');render()}catch(err){save.disabled=false;if(err.status===409){setMessage('Linha alterada por outro operador. Recarregando os dados…','error');await load(current.id)}else setMessage(uiErrorMessage(err,'Não foi possível registrar a recontagem.'),'error')}});card.append(form)}linesBox.append(card)}
function appendHistoryCard(line){let state=line.state||'',card=document.createElement('article');card.className='inventory-line inventory-review-line'+(state==='DIVERGENT'?' divergent':state==='MATCH'?' match':'');card.dataset.skuId=line.sku_id;let head=document.createElement('div');head.className='inventory-line-head';let title=document.createElement('div'),strong=document.createElement('strong'),meta=document.createElement('small');strong.textContent=line.description;meta.textContent='SKU '+line.code+(line.barcode?' · '+line.barcode:'')+' · '+line.unit;title.append(strong,meta);head.append(title);if(state){let badge=document.createElement('span');badge.className='badge';badge.textContent=inventoryStateLabel(state);head.append(badge)}card.append(head);let first=document.createElement('div');first.className='inventory-recount-result';let fs=document.createElement('strong'),fm=document.createElement('small');fs.textContent='Primeira contagem: '+(line.first_quantity!==undefined?line.first_quantity+' '+line.unit:'não realizada');fm.textContent=(line.first_counted_by?' por '+line.first_counted_by:'')+(line.first_counted_at?' · '+auditTime(line.first_counted_at):'');first.append(fs,fm);card.append(first);if(line.recount_quantity!==undefined){let recount=document.createElement('div');recount.className='inventory-recount-result';let rs=document.createElement('strong'),rm=document.createElement('small');rs.textContent='Recontagem: '+line.recount_quantity+' '+line.unit;rm.textContent=(line.recounted_by?' por '+line.recounted_by:'')+(line.recounted_at?' · '+auditTime(line.recounted_at):'');recount.append(rs,rm);card.append(recount)}if(line.reference_quantity!==undefined){let compare=document.createElement('div');compare.className='inventory-review-grid';[['Referência',line.reference_quantity],['Resultado físico',line.effective_quantity],['Diferença',line.difference]].forEach(pair=>{let box=document.createElement('div'),sm=document.createElement('small'),val=document.createElement('strong');sm.textContent=pair[0];val.textContent=pair[1]+' '+line.unit;box.append(sm,val);compare.append(box)});card.append(compare)}linesBox.append(card)}
function render(){if(!current)return;recompute();setFilterLabels();updateHeader();renderTerminalActions();linesBox.textContent='';let rows=current.lines.filter(line=>matches(line)&&visibleByFilter(line));if(!rows.length){let p=document.createElement('p');p.className='catalog-empty';p.textContent=historyMode()?'Nenhum item neste filtro histórico.':reviewMode()?'Nenhum item neste filtro de revisão.':'Nenhum item neste filtro.';linesBox.append(p);return}if(historyMode()){rows.forEach(appendHistoryCard);return}if(reviewMode()){rows.forEach(appendReviewCard);return}rows.forEach(line=>{let card=document.createElement('article');card.className='inventory-line';card.dataset.skuId=line.sku_id;let head=document.createElement('div');head.className='inventory-line-head';let title=document.createElement('div'),strong=document.createElement('strong'),meta=document.createElement('small');strong.textContent=line.description;meta.textContent='SKU '+line.code+(line.barcode?' · '+line.barcode:'')+' · '+line.unit;title.append(strong,meta);let badge=document.createElement('span');badge.className='badge';badge.textContent=counted(line)?'Contado':'Pendente';head.append(title,badge);let form=document.createElement('form');form.className='inventory-count-form';let lab=document.createElement('label');lab.textContent='Quantidade física ('+line.unit+')';let input=document.createElement('input');input.inputMode='decimal';input.autocomplete='off';input.placeholder='0';input.value=counted(line)?line.physical_quantity:'';input.required=true;input.disabled=!canEdit();lab.append(input);let save=document.createElement('button');save.type='submit';save.textContent=counted(line)?'Atualizar':'Salvar';save.disabled=!canEdit();form.append(lab,save);let audit=document.createElement('small');audit.className='hint';if(counted(line))audit.textContent='Salvo'+(line.counted_by?' por '+line.counted_by:'')+(line.counted_at?' · '+auditTime(line.counted_at):'');form.addEventListener('submit',async e=>{e.preventDefault();if(!canEdit())return;save.disabled=true;setMessage('Salvando…');try{let out=await api('/api/inventory-validations/'+current.id+'/lines/'+line.sku_id+'/count',{method:'PUT',body:JSON.stringify({physical_quantity:requestDecimal(input.value),expected_version:line.version})});Object.assign(line,out.line);current.status=out.status;setMessage('Contagem salva.','ok');if(out.status==='REVIEW'){await load(current.id);loadList();return}render()}catch(err){save.disabled=false;if(err.status===409){setMessage('Contagem alterada por outro operador. Recarregando os dados…','error');await load(current.id)}else setMessage(uiErrorMessage(err,'Não foi possível salvar a contagem.'),'error')}});card.append(head,form,audit);linesBox.append(card)})}
async function load(id){setMessage('Carregando…');try{let base=await api('/api/inventory-validations/'+id+'/counting');if(base.status==='REVIEW'){current=await api('/api/inventory-validations/'+id+'/review');current.review_mode=true;current.history_mode=false;filter='pending'}else if(base.status==='COMPLETED'||base.status==='CANCELLED'){current=await api('/api/inventory-validations/'+id+'/history');current.history_mode=true;current.review_mode=false;filter='all'}else{current=base;current.review_mode=false;current.history_mode=false;filter='pending'}idInput.value=current.id;workspace.hidden=false;let u=new URL(location.href);u.searchParams.set('id',current.id);history.replaceState(null,'',u);setMessage('');document.querySelectorAll('[data-inventory-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.inventoryFilter===filter));render();workspace.scrollIntoView({behavior:'smooth',block:'start'})}catch(err){current=null;workspace.hidden=true;setMessage(uiErrorMessage(err,'Não foi possível abrir o inventário.'),'error')}}
function focusSKU(skuID){filter='all';document.querySelectorAll('[data-inventory-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.inventoryFilter==='all'));search.value='';render();let card=linesBox.querySelector('[data-sku-id="'+skuID+'"]');if(!card)return false;card.classList.add('inventory-highlight');card.scrollIntoView({behavior:'smooth',block:'center'});card.querySelector('input')?.focus();setTimeout(()=>card.classList.remove('inventory-highlight'),1800);return true}
async function loadWarehouses(){try{let rows=await api('/api/inventory-validations/warehouses');[listWarehouse,createWarehouse].filter(Boolean).forEach(sel=>{let first=sel===listWarehouse?'<option value="">Todos</option>':'<option value="">Selecione</option>';sel.innerHTML=first;rows.forEach(w=>{let o=document.createElement('option');o.value=w.id;o.textContent=w.name;sel.append(o)})});applyInventoryCreatePending()}catch(err){setListMessage(uiErrorMessage(err,'Não foi possível carregar os depósitos.'),'error')}}
function listQuery(){let q=new URLSearchParams();if(listStatus?.value)q.set('status',listStatus.value);if(listType?.value)q.set('type',listType.value);if(listWarehouse?.value)q.set('warehouse_id',listWarehouse.value);if(listResponsible?.value.trim())q.set('responsible',listResponsible.value.trim());if(listFrom?.value)q.set('from',listFrom.value);if(listTo?.value)q.set('to',listTo.value);q.set('limit',String(listLimit));q.set('offset',String(listOffset));return q}
async function loadList(){if(!listBox)return;setListMessage('Carregando inventários…');listBox.textContent='';try{let out=await api('/api/inventory-validations?'+listQuery().toString());setListMessage(out.items.length?'':'Nenhum inventário encontrado.');out.items.forEach(item=>{let card=document.createElement('article');card.className='inventory-admin-card';let info=document.createElement('div');let title=document.createElement('strong');title.textContent='#'+item.id+' · '+inventoryTypeLabel(item.type)+' · '+statusLabel(item.status);let meta=document.createElement('small');meta.textContent=item.warehouse+' · '+item.responsible+(item.started_at?' · '+auditTime(item.started_at):'');let prog=document.createElement('small');prog.textContent=(item.status==='OPEN'||item.status==='COUNTING')?(item.counted+' de '+item.total+' contados'):(item.total+' item(ns)');info.append(title,meta,prog);let btn=document.createElement('button');btn.type='button';btn.className='secondary';btn.textContent=actionLabel(item.status);btn.addEventListener('click',()=>load(item.id));card.append(info,btn);listBox.append(card)});listPrev.disabled=out.offset<=0;listNext.disabled=!out.more;listPaging.hidden=out.items.length===0&&out.offset===0}catch(err){setListMessage(uiErrorMessage(err,'Não foi possível listar os inventários.'),'error')}}
if(listForm)listForm.addEventListener('submit',e=>{e.preventDefault();listOffset=0;loadList()});
if(listClear)listClear.addEventListener('click',()=>{listForm?.reset();listOffset=0;loadList()});
if(listPrev)listPrev.addEventListener('click',()=>{listOffset=Math.max(0,listOffset-listLimit);loadList()});
if(listNext)listNext.addEventListener('click',()=>{listOffset+=listLimit;loadList()});
if(createTotal)if(createTotal)createTotal.addEventListener('submit',async e=>{e.preventDefault();let submit=e.submitter||createTotal.querySelector('button[type="submit"]');if(submit?.dataset.busy==='1')return;let pending=readInventoryCreatePending();if(pending&&pending.type!=='TOTAL'){applyInventoryCreatePending();return}if(!pending&&!requireFields(createTotal,listMsg))return;let warehouseId=pending?+pending.warehouse_id:Number(createWarehouse.value);if(!warehouseId){setListMessage('Selecione um depósito.','error');return}if(!pending){pending={type:'TOTAL',operation_id:crypto.randomUUID(),warehouse_id:warehouseId};saveInventoryCreatePending(pending);applyInventoryCreatePending()}await runLocked(submit,async()=>{setListMessage('Criando inventário total…');try{let out=await api('/api/inventory-validations/total',{method:'POST',body:JSON.stringify({operation_id:pending.operation_id,warehouse_id:pending.warehouse_id})});clearInventoryCreatePending();applyInventoryCreatePending();setListMessage('Inventário total criado.','ok');listOffset=0;await loadList();await load(out.id)}catch(err){if(definitiveInventoryCreateError(err)){clearInventoryCreatePending();applyInventoryCreatePending()}else applyInventoryCreatePending();setListMessage(uiErrorMessage(err,'Não foi possível confirmar a criação do inventário total. Reenvie a mesma tentativa.'),'error')}})});
if(createBlind)createBlind.addEventListener('submit',async e=>{e.preventDefault();let submit=e.submitter||createBlind.querySelector('button[type="submit"]');if(submit?.dataset.busy==='1')return;let pending=readInventoryCreatePending();if(pending&&pending.type!=='BLIND'){applyInventoryCreatePending();return}if(!pending){pending={type:'BLIND',operation_id:crypto.randomUUID()};saveInventoryCreatePending(pending);applyInventoryCreatePending()}await runLocked(submit,async()=>{setListMessage('Criando inventário cego…');try{let out=await api('/api/inventory-validations/blind',{method:'POST',body:JSON.stringify({operation_id:pending.operation_id})});clearInventoryCreatePending();applyInventoryCreatePending();setListMessage('Inventário cego criado.','ok');listOffset=0;await loadList();await load(out.id)}catch(err){if(definitiveInventoryCreateError(err)){clearInventoryCreatePending();applyInventoryCreatePending()}else applyInventoryCreatePending();setListMessage(uiErrorMessage(err,'Não foi possível confirmar a criação do inventário cego. Reenvie a mesma tentativa.'),'error')}})});
openForm.addEventListener('submit',e=>{e.preventDefault();let id=Number(idInput.value);if(id>0)load(id)});
search.addEventListener('input',render);
document.querySelectorAll('[data-inventory-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.inventoryFilter;document.querySelectorAll('[data-inventory-filter]').forEach(x=>x.classList.toggle('selected',x===b));render()}));
initScanner('scanInventory',async code=>{if(!current)return;setMessage('Localizando código…');try{let r=await api('/api/inventory-validations/'+current.id+'/lookup?barcode='+encodeURIComponent(code));if(!r.known){setMessage('Código não localizado no catálogo.','error');return}if(!r.in_inventory){setMessage('Item não pertence a este inventário.','error');return}if(focusSKU(r.sku_id))setMessage(historyMode()?'Item localizado no histórico.':reviewMode()?'Item localizado na revisão.':'Item localizado. Informe a quantidade física.','ok')}catch(err){setMessage(uiErrorMessage(err,'Não foi possível localizar o código.'),'error')}});
applyInventoryCreatePending();loadWarehouses();loadList();let initial=Number(new URLSearchParams(location.search).get('id'));if(initial>0)load(initial)
}

function initForcedPassword(){let f=document.getElementById('forcedPasswordForm');if(!f)return;let st=document.getElementById('forcedPasswordStatus');f.addEventListener('submit',async e=>{e.preventDefault();let submit=e.submitter||f.querySelector('button[type="submit"]');if(submit?.dataset.busy==='1')return;if(!requireFields(f,st))return;await runLocked(submit,async()=>{setFeedback(st,'loading','Salvando nova senha…');try{await api('/api/me/password',{method:'PATCH',body:JSON.stringify({current_password:forcedCurrent.value,new_password:forcedNew.value,confirm_password:forcedConfirm.value})});setFeedback(st,'success','Senha alterada.');location.href='/stock'}catch(err){setFeedback(st,'error',uncertainWriteError(err)?'Não foi possível confirmar a alteração da senha. Não repita automaticamente; tente entrar com a nova senha.':uiErrorMessage(err,'Não foi possível alterar a senha por uma falha do sistema. Tente novamente.'))}})})}
initForcedPassword();initAccount();initStock();initMovement();initInventory();initCatalog();initFiscal();initAssets();initAdmin();

async function initReports(){
let form=document.getElementById('reportForm');if(!form)return;
let exportRows=[],exportType='';
let start=document.getElementById('reportStart'),end=document.getElementById('reportEnd'),startLabel=document.getElementById('reportStartLabel'),endLabelText=document.getElementById('reportEndLabelText'),type=document.getElementById('reportType'),wh=document.getElementById('warehouse'),status=document.getElementById('reportStatus'),result=document.getElementById('reportResult'),head=document.getElementById('reportHead'),body=document.getElementById('reportBody'),title=document.getElementById('reportTitle'),meta=document.getElementById('reportMeta'),csvBtn=document.getElementById('reportCSV'),printBtn=document.getElementById('reportPrint');
try{await loadWarehouses(true,'/api/reports/warehouses')}catch(err){setFeedback(status,'error',uiErrorMessage(err,'Não foi possível carregar os depósitos do relatório.'));return}
function localDate(d){let y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return y+'-'+m+'-'+day}
function clearResult(){result.hidden=true;body.textContent='';exportRows=[];exportType='';csvBtn.disabled=true;printBtn.disabled=true;setFeedback(status,'','')}
function markPeriod(kind){document.querySelectorAll('[data-period]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.period===kind?'true':'false'))}
function setPeriod(kind){let now=new Date(),a=new Date(now.getFullYear(),now.getMonth(),now.getDate()),b=new Date(a);if(kind==='week'){a.setDate(a.getDate()-a.getDay())}else if(kind==='month'){a=new Date(now.getFullYear(),now.getMonth(),1)}start.value=localDate(a);end.value=localDate(b);markPeriod(kind);clearResult()}
function setCustomPeriod(){markPeriod('custom');clearResult();(type.value==='SALDO'?end:start).focus()}
function syncReportType(){let balance=type.value==='SALDO';startLabel.hidden=balance;start.required=!balance;endLabelText.textContent=balance?'Data de corte':'Até';document.querySelector('[data-period="week"]').hidden=balance;document.querySelector('[data-period="month"]').hidden=balance;if(balance)markPeriod(end.value===localDate(new Date())?'today':'custom')}
document.querySelectorAll('[data-period]').forEach(b=>{b.setAttribute('aria-pressed','false');b.onclick=()=>b.dataset.period==='custom'?setCustomPeriod():setPeriod(b.dataset.period)});[start,end].forEach(x=>x.addEventListener('change',()=>{markPeriod('custom');clearResult()}));type.addEventListener('change',()=>{syncReportType();clearResult()});wh.addEventListener('change',clearResult);setPeriod('today');syncReportType();
function bounds(){let a=new Date(start.value+'T00:00:00'),b=new Date(end.value+'T00:00:00');b.setDate(b.getDate()+1);return {start:a.toISOString(),end:b.toISOString()}}
function cell(tr,text){let td=document.createElement('td');td.textContent=text;tr.append(td)}
function header(labels){head.textContent='';let tr=document.createElement('tr');labels.forEach(x=>{let th=document.createElement('th');th.scope='col';th.textContent=x;tr.append(th)});head.append(tr)}
function money(v){let n=Number(v);return Number.isFinite(n)?new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n):v}
form.onsubmit=async e=>{e.preventDefault();if(!requireFields(form,status,'Informe o período do relatório.'))return;if(type.value!=='SALDO'&&start.value>end.value){setFeedback(status,'error','A data inicial não pode ser posterior à data final.');return}setFeedback(status,'loading','Gerando relatório…');result.hidden=true;body.textContent='';let p=bounds(),qs=new URLSearchParams();if(wh.value)qs.set('warehouse_id',wh.value);let rows;
try{if(type.value==='SALDO'){qs.set('before',p.end);rows=await api('/api/reports/balance?'+qs)}else{qs.set('type',type.value);qs.set('start',p.start);qs.set('end',p.end);rows=await api('/api/reports/movements?'+qs)}}catch(err){setFeedback(status,'error',uiErrorMessage(err,'Não foi possível gerar o relatório.'));return}
setFeedback(status,'','');result.hidden=false;exportRows=rows;exportType=type.value;csvBtn.disabled=!rows.length;printBtn.disabled=!rows.length;let label=type.options[type.selectedIndex].text;title.textContent=label;meta.textContent=type.value==='SALDO'?'Data de corte: '+end.value:(start.value===end.value?'Data: '+start.value:'Período: '+start.value+' a '+end.value);
if(type.value==='SALDO'){header(['Produto / SKU','Depósito','Saldo','Preço médio']);rows.forEach(r=>{let tr=document.createElement('tr');cell(tr,r.item+(r.sku?' · '+r.sku:''));cell(tr,r.warehouse);cell(tr,displayDecimal(r.quantity)+' '+r.unit);cell(tr,money(r.avg_cost));body.append(tr)})}else{header(['Data','Produto / SKU','Depósito','Quantidade','Custo unitário','Documento / fornecedor']);rows.forEach(r=>{let tr=document.createElement('tr');cell(tr,new Date(r.occurred_at).toLocaleString('pt-BR'));cell(tr,r.item+(r.sku?' · '+r.sku:''));cell(tr,r.warehouse);cell(tr,displayDecimal(r.quantity)+' '+r.unit);cell(tr,money(r.unit_cost));cell(tr,[r.document_number,r.supplier_name].filter(Boolean).join(' · '));body.append(tr)})}
if(!rows.length){let tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=type.value==='SALDO'?4:6;td.textContent='Nenhum registro encontrado para os filtros selecionados.';tr.append(td);body.append(tr)}
result.scrollIntoView({block:'nearest',behavior:'smooth'})}
function csvValue(v){let s=String(v??'');if(/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function csvText(v){let s=String(v??'');return s&&/^\d+$/.test(s)?'\t'+s:s}
function exportCSV(){if(!exportRows.length)return;let headers,lines;if(exportType==='SALDO'){headers=['Produto','SKU','Código de barras','Depósito','Saldo','Unidade','Preço médio'];lines=exportRows.map(r=>[r.item,r.sku,csvText(r.barcode),r.warehouse,r.quantity,r.unit,r.avg_cost])}else{headers=['Data','Tipo','Produto','SKU','Código de barras','Depósito','Quantidade','Unidade','Custo unitário','Documento','Fornecedor','Responsável'];lines=exportRows.map(r=>[new Date(r.occurred_at).toLocaleString('pt-BR'),r.type,r.item,r.sku,csvText(r.barcode),r.warehouse,r.quantity,r.unit,r.unit_cost,r.document_number,r.supplier_name,r.responsible])}let csv='\uFEFF'+[headers,...lines].map(row=>row.map(csvValue).join(';')).join('\r\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=exportType==='SALDO'?'relatorio-saldo-ate-'+end.value+'.csv':'relatorio-'+exportType.toLowerCase()+'-'+start.value+'-a-'+end.value+'.csv';document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url)}
csvBtn.disabled=true;printBtn.disabled=true;csvBtn.addEventListener('click',exportCSV);printBtn.addEventListener('click',()=>window.print())
}

initReports();
